<script setup lang="ts">
import{computed,defineAsyncComponent,onMounted,reactive,ref}from"vue";import{InfoFilled,RefreshRight}from"@element-plus/icons-vue";import{useRoute,useRouter}from"vue-router";import{fetchSearchRankings,type SearchListType,type SearchPayload}from"../api/searchRanking";import{useThemeStore}from"../stores/theme";
const Chart=defineAsyncComponent(()=>import("../components/ContentRankingChart.vue")),route=useRoute(),router=useRouter(),theme=useThemeStore();const listTypes:SearchListType[]=["总榜","新用户榜"];const filters=reactive({date:typeof route.query.date==="string"?route.query.date:"2026-09-14",listType:(route.query.list_type==="新用户榜"?"新用户榜":"总榜")as SearchListType,page:1,page_size:15,sort:"rank",direction:"asc"}),data=ref<SearchPayload|null>(null),loading=ref(false),error=ref(""),drawer=ref(false),nf=new Intl.NumberFormat("zh-CN");const num=(v:number|null|undefined)=>v==null?"--":nf.format(v);const change=(v:number|null)=>v==null?"--":`${v>=0?"↑":"↓"}${Math.abs(v).toFixed(2)}%`;
async function load(){loading.value=true;error.value="";router.replace({query:{date:filters.date,list_type:filters.listType,page:String(filters.page),sort:filters.sort,direction:filters.direction}});try{data.value=await fetchSearchRankings({date:filters.date,list_type:filters.listType,page:filters.page,page_size:filters.page_size,sort:filters.sort,direction:filters.direction})}catch(e){error.value="热搜榜单加载失败。";console.error(e)}finally{loading.value=false}}
function list(v:SearchListType){filters.listType=v;filters.page=1;load()}function sort(v:string){if(filters.sort===v)filters.direction=filters.direction==="asc"?"desc":"asc";else{filters.sort=v;filters.direction=v==="rank"?"asc":"desc"}filters.page=1;load()}function page(v:number){filters.page=v;load()}
const option=computed(()=>({color:[theme.current.primary],grid:{left:130,right:30,top:12,bottom:24},tooltip:{trigger:"axis",axisPointer:{type:"shadow"}},xAxis:{type:"value"},yAxis:{type:"category",data:data.value?.top10.slice().reverse().map(x=>x.title.length>10?x.title.slice(0,10)+"…":x.title)??[]},series:[{type:"bar",barMaxWidth:18,data:data.value?.top10.slice().reverse().map(x=>x.search_uv)??[]}]}));onMounted(load);
</script>
<template><main class="main-content page-stack"><header class="page-intro"><div><h2>热搜榜单 Top30</h2><p>按搜索UV和搜索VV查看内容搜索热度。</p></div><button class="source-button" @click="drawer=true"><el-icon><InfoFilled/></el-icon>数据说明</button></header><section class="filter-bar ranking-filter"><label><span>数据日期</span><el-date-picker v-model="filters.date" type="date" value-format="YYYY-MM-DD"/></label><div class="ranking-tabs" role="tablist"><button v-for="value in listTypes" :key="value" role="tab" :class="{active:filters.listType===value}" @click="list(value)">{{value}}</button></div><el-button type="primary" :loading="loading" @click="load"><el-icon><RefreshRight/></el-icon>更新榜单</el-button><div class="freshness"><span class="status-dot"></span><div><b>真实Top30</b><small>{{data?.meta.component??'--'}}</small></div></div></section><el-alert v-if="error" :title="error" type="error" show-icon :closable="false"/><section class="ranking-summary-grid"><article class="metric-item"><div class="metric-label"><span>榜单记录</span><small>当前日期</small></div><strong>{{data?.pagination.total??0}} 条</strong></article><article class="metric-item"><div class="metric-label"><span>最高搜索UV</span><small>Top1</small></div><strong>{{num(data?.top10[0]?.search_uv)}}</strong></article><article class="metric-item"><div class="metric-label"><span>最高搜索VV</span><small>Top1</small></div><strong>{{num(data?.top10[0]?.search_vv)}}</strong></article><article class="metric-item"><div class="metric-label"><span>新入榜</span><small>当前页</small></div><strong>{{data?.items.filter(x=>x.status==='新入榜').length??0}} 个</strong></article></section><section class="panel"><div class="panel-head"><div><h2>搜索UV Top10</h2><p>{{filters.listType}}</p></div></div><Chart v-if="data?.top10.length" class="ranking-chart" :option="option"/></section><section class="panel ranking-detail-panel"><div class="panel-head ranking-table-head"><div><h2>热搜明细</h2><p>服务端分页，保留内容元数据</p></div><div class="ranking-sort"><span>排序</span><button :class="{active:filters.sort==='rank'}" @click="sort('rank')">排名</button><button :class="{active:filters.sort==='search_uv'}" @click="sort('search_uv')">搜索UV</button><button :class="{active:filters.sort==='search_vv'}" @click="sort('search_vv')">搜索VV</button><button :class="{active:filters.sort==='day_change'}" @click="sort('day_change')">昨日环比</button></div></div><div v-loading="loading" class="table-wrap"><table class="client-table ranking-table"><thead><tr><th>排名</th><th>内容名称</th><th>搜索UV</th><th>搜索VV</th><th>昨日环比</th><th>周环比</th><th>内容类型</th><th>地区</th><th>剧种</th><th>题材</th><th>状态</th></tr></thead><tbody><tr v-for="x in data?.items" :key="x.rank"><td><span class="rank-badge">{{x.rank}}</span></td><td class="ranking-title"><strong>{{x.title}}</strong><small>{{x.season_id?`ID ${x.season_id}`:'--'}}</small></td><td>{{num(x.search_uv)}}</td><td>{{num(x.search_vv)}}</td><td :class="x.day_change!==null&&x.day_change>=0?'change-up':'change-down'">{{change(x.day_change)}}</td><td>{{change(x.week_change)}}</td><td>{{x.content_type??'--'}}</td><td>{{x.producer_region??'--'}}</td><td>{{x.genre??'--'}}</td><td class="genre-cell">{{x.topic_tag??'--'}}</td><td><span class="status-badge">{{x.status??'--'}}</span></td></tr></tbody></table></div><div class="table-footer"><el-pagination background layout="prev,pager,next,total" :current-page="filters.page" :page-size="filters.page_size" :total="data?.pagination.total??0" @current-change="page"/></div></section><el-drawer v-model="drawer" title="热搜榜单来源与口径" size="440px"><div class="source-drawer"><section><span>数据源</span><strong>{{data?.meta.source??'--'}}</strong></section><section><span>接口</span><strong>{{data?.meta.component??'--'}}</strong></section><section><span>原始字段</span><div class="field-tags"><code v-for="f in data?.meta.original_fields" :key="f">{{f}}</code></div></section><p>搜索VV对应原始 search_cnt。新用户榜明确使用 new_or_old=new，不与全部用户榜混用。</p></div></el-drawer></main></template>
